function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.fillStyle = '#663300';
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillRect(W/2 - 50, H/2 - 50, 100, 100);
  ctx.strokeRect(W/2 - 50, H/2 - 50, 100, 100);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 120, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 120);
  ctx.lineTo(W/2 - 30, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 120);
  ctx.lineTo(W/2 + 30, H/2 + 150);
  ctx.stroke();

  // book opening
  ctx.fillStyle = '#663300';
  ctx.save();
  ctx.translate(W/2 - 50, H/2 - 50);
  ctx.rotate(Math.sin(t) * Math.PI / 4);
  ctx.fillRect(0, 0, 50, 100);
  ctx.restore();
  ctx.strokeRect(W/2 - 50, H/2 - 50, 50, 100);

  ctx.restore();
}
